package com.genymobile.scrcpy;
import java.io.*;import java.nio.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.zip.*;
/** Resource path -> ID lookup, including renamed APK file paths; no application code loading. */
final class NativeAlphaResourceTable {
 final byte[] b;NativeAlphaResourceTable(byte[] b)throws IOException {this.b=b;if(b.length<12||b.length>16*1024*1024||u16(0)!=2)throw new IOException("resource_table_header");}
 int u8(int p)throws IOException{check(p,1);return b[p]&255;}int u16(int p)throws IOException{check(p,2);return (b[p]&255)|((b[p+1]&255)<<8);}int i32(int p)throws IOException{check(p,4);return ByteBuffer.wrap(b,p,4).order(ByteOrder.LITTLE_ENDIAN).getInt();}
 void check(int p,int n)throws IOException{if(p<0||n<0||p>b.length-n)throw new IOException("resource_table_bounds");}
 int end(int p,int limit)throws IOException{int h=u16(p+2),n=i32(p+4);if(h<8||n<h||p>limit-n)throw new IOException("resource_chunk_bounds");return p+n;}
 int[] len8(int p)throws IOException{int n=u8(p++);if((n&128)!=0)n=((n&127)<<8)|u8(p++);return new int[]{n,p};}
 int[] len16(int p)throws IOException{int n=u16(p);p+=2;if((n&0x8000)!=0){n=((n&0x7fff)<<16)|u16(p);p+=2;}return new int[]{n,p};}
 List<String> strings(int at,int limit)throws IOException {int e=end(at,limit),count=i32(at+8),flags=i32(at+16),base=at+i32(at+20),head=u16(at+2);if(count<0||count>500000||at+head>e-count*4)throw new IOException("resource_string_count");List<String> out=new ArrayList<>();for(int i=0;i<count;i++){int p=base+i32(at+head+i*4);int[] n;if((flags&256)!=0){n=len8(p);n=len8(n[1]);p=n[1];check(p,n[0]);if(p>e-n[0])throw new IOException("resource_string_bounds");out.add(new String(b,p,n[0],StandardCharsets.UTF_8));}else{n=len16(p);p=n[1];check(p,n[0]*2);if(p>e-n[0]*2)throw new IOException("resource_string_bounds");out.add(new String(b,p,n[0]*2,StandardCharsets.UTF_16LE));}}return out;}
 Map<String,Set<Integer>> paths()throws IOException {List<String> pool=null;Map<String,Set<Integer>> out=new HashMap<>();int total=end(0,b.length);for(int p=u16(2);p<total;){int e=end(p,total),t=u16(p);if(t==1&&pool==null)pool=strings(p,total);if(t==0x200&&pool!=null){int pkg=i32(p+8),h=u16(p+2),offset=h>=288?i32(p+284):0;for(int q=p+h;q<e;){int qe=end(q,e);if(u16(q)==0x201){int tid=u8(q+8)+offset,flags=u8(q+9),count=i32(q+12),start=q+i32(q+16),head=u16(q+2);if(count<0||count>65536||start<q+head||start>qe)throw new IOException("resource_entries");for(int i=0;i<count;i++){int index=i,pos;if((flags&1)!=0){index=u16(q+head+i*4);pos=u16(q+head+i*4+2)*4;}else if((flags&2)!=0){int v=u16(q+head+i*2);if(v==65535)continue;pos=v*4;}else{pos=i32(q+head+i*4);if(pos==-1)continue;}int entry=start+pos;check(entry,8);if(entry>qe-8)throw new IOException("resource_entry_bounds");int ef=u16(entry+2);if((ef&1)!=0)continue;int type,value;if((ef&8)!=0){type=ef>>>8;value=i32(entry+4);}else{int v=entry+u16(entry);if(v>qe-8)throw new IOException("resource_value_bounds");type=u8(v+3);value=i32(v+4);}if(type==3&&value>=0&&value<pool.size()){String path=pool.get(value);if(path.startsWith("res/"))out.computeIfAbsent(path,k->new LinkedHashSet<>()).add((pkg<<24)|(tid<<16)|index);}}}q=qe;}}p=e;}return out;}
 static Map<String,Set<Integer>> read(String apk)throws IOException {try(ZipFile z=new ZipFile(apk)){ZipEntry e=z.getEntry("resources.arsc");if(e==null||e.getSize()>16*1024*1024)throw new IOException("resource_table_unavailable");try(InputStream in=z.getInputStream(e)){byte[] b=in.readNBytes(16*1024*1024+1);return new NativeAlphaResourceTable(b).paths();}}}
}
